113	/**
114	 * Fetch attachments from Resend API (inbound webhooks only include metadata).
115	 */
116	async function fetchResendAttachments(
117	  resendApiKey: string,
118	  emailId: string,
119	  maxFileSizeBytes: number,
120	): Promise<{ filename: string; content: Uint8Array }[]> {
121	  const attachmentFiles: { filename: string; content: Uint8Array }[] = [];
122	
123	  // First try the receiving attachments endpoint
124	  let listRes = await fetch(
125	    `https://api.resend.com/emails/receiving/${emailId}/attachments`,
126	    { headers: { Authorization: `Bearer ${resendApiKey}` } }
127	  );
128	
129	  // If receiving endpoint fails, try the regular email endpoint
130	  if (!listRes.ok) {
131	    const errText = await listRes.text();
132	    console.error("Resend receiving attachments failed:", listRes.status, errText);
133	    await logSystemError({
134	      function_name: "email-ingest",
135	      error_type: "RESEND_ATTACHMENT_FETCH",
136	      severity: "warning",
137	      error_message: `Resend API ${listRes.status}: ${errText.slice(0, 500)}`,
138	      context_json: { email_id: emailId, endpoint: "receiving" },
139	    });
140	
141	    // Fallback: try fetching email details which may include attachments
142	    listRes = await fetch(
143	      `https://api.resend.com/emails/${emailId}`,
144	      { headers: { Authorization: `Bearer ${resendApiKey}` } }
145	    );
146	    if (!listRes.ok) {
147	      console.error("Resend email details also failed:", listRes.status);
148	      return attachmentFiles;
149	    }
150	    const emailData = await listRes.json();
151	    // Check if email data has attachments inline
152	    if (emailData.attachments && Array.isArray(emailData.attachments)) {
153	      for (const att of emailData.attachments) {
154	        if (!att.filename || !hasAllowedExtension(att.filename)) continue;
155	        if (att.content) {
156	          const fileContent = Uint8Array.from(atob(att.content), (c: string) => c.charCodeAt(0));
157	          if (fileContent.byteLength <= Math.min(maxFileSizeBytes, MAX_ATTACHMENT_SIZE_BYTES)) {
158	            attachmentFiles.push({ filename: att.filename, content: fileContent });
159	          }
160	        }
161	      }
162	    }
163	    return attachmentFiles;
164	  }
165	
166	  const listData = await listRes.json();
167	  const attachments = listData.data || listData || [];
168	  let count = 0;
169	
170	  console.log("Resend attachments response:", JSON.stringify(listData).slice(0, 500));
171	
172	  for (const att of (Array.isArray(attachments) ? attachments : [])) {
173	    if (count >= MAX_ATTACHMENTS_PER_EMAIL) break;
174	    if (!att.filename || !hasAllowedExtension(att.filename)) continue;
175	    if (att.size && att.size > Math.min(maxFileSizeBytes, MAX_ATTACHMENT_SIZE_BYTES)) continue;
176	
177	    try {
178	      const downloadRes = await fetch(att.download_url);
179	      if (!downloadRes.ok) {
180	        console.error(`Failed to download attachment ${att.filename}: ${downloadRes.status}`);
181	        continue;
182	      }
183	      const buffer = await downloadRes.arrayBuffer();
184	      if (buffer.byteLength > Math.min(maxFileSizeBytes, MAX_ATTACHMENT_SIZE_BYTES)) continue;
185	      attachmentFiles.push({ filename: att.filename, content: new Uint8Array(buffer) });
186	      count++;
187	    } catch (e) {
188	      console.error(`Failed to download Resend attachment ${att.filename}:`, e);
189	    }
190	  }
191	
192	  return attachmentFiles;
193	}
