18	/** Send an email via Resend API */
19	async function sendViaResend(
20	  apiKey: string,
21	  from: { email: string; name: string },
22	  to: string,
23	  subject: string,
24	  htmlContent: string
25	): Promise<{ ok: boolean; status: number; body: string; errorMessage?: string }> {
26	  const res = await fetch("https://api.resend.com/emails", {
27	    method: "POST",
28	    headers: {
29	      "Authorization": `Bearer ${apiKey}`,
30	      "Content-Type": "application/json",
31	    },
32	    body: JSON.stringify({
33	      from: `${from.name} <${from.email}>`,
34	      to: [to],
35	      subject,
36	      html: htmlContent,
37	    }),
38	  });
39	
40	  const body = await res.text();
41	  let errorMessage: string | undefined;
42	
43	  if (!res.ok) {
44	    try {
45	      const parsed = JSON.parse(body);
46	      errorMessage = parsed.message || parsed.error?.message;
47	    } catch { /* ignore */ }
48	  }
49	
50	  return { ok: res.ok, status: res.status, body, errorMessage };
51	}
