17	    const authHeader = req.headers.get("Authorization");
18	    if (!authHeader?.startsWith("Bearer ")) throw new Error("No auth");
19	
20	    const supabaseUser = createClient(SUPABASE_URL, anonKey, {
21	      global: { headers: { Authorization: authHeader } },
22	    });
23	    const token = authHeader.replace("Bearer ", "");
24	    const { data: claimsData, error: claimsError } = await supabaseUser.auth.getClaims(token);
25	    if (claimsError || !claimsData?.claims) throw new Error("Unauthorized");
26	    const userId = claimsData.claims.sub as string;
27	
28	    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
29	
30	    const { data: roles } = await supabase.from("user_roles").select("role").eq("user_id", userId);
31	    if (!roles?.some((r: any) => r.role === "admin")) {
32	      return new Response(JSON.stringify({ error: "Admin access required" }), {
33	        status: 403, headers: { ...corsHeaders, "Content-Type": "application/json" },
34	      });
35	    }
36	
37	    // Parse optional date range from request body
38	    let rangeDays = 30;
39	    let rangeFrom: string | null = null;
40	    let rangeTo: string | null = null;
41	    try {
42	      const text = await req.text();
43	      if (text) {
44	        const body = JSON.parse(text);
45	        if (body.from) rangeFrom = body.from;
46	        if (body.to) rangeTo = body.to;
47	        if (body.days && typeof body.days === "number") rangeDays = Math.min(body.days, 365);
48	      }
49	    } catch { /* empty body = default 30 days */ }
50	
51	    // Validate date inputs
52	    if (rangeFrom && isNaN(Date.parse(rangeFrom))) {
53	      return new Response(JSON.stringify({ error: "Invalid 'from' date format" }), {
54	        status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
55	      });
56	    }
57	    if (rangeTo && isNaN(Date.parse(rangeTo))) {
58	      return new Response(JSON.stringify({ error: "Invalid 'to' date format" }), {
59	        status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
60	      });
61	    }
62	
63	    const now = Date.now();
64	    const rangeStartDate = rangeFrom
65	      ? new Date(rangeFrom)
66	      : new Date(now - rangeDays * 24 * 60 * 60 * 1000);
67	    const rangeEndDate = rangeTo ? new Date(rangeTo) : new Date(now);
68	    // Ensure end date includes full day
69	    rangeEndDate.setHours(23, 59, 59, 999);
70	
71	    const rangeStartISO = rangeStartDate.toISOString();
72	    const rangeEndISO = rangeEndDate.toISOString();
73	    const sevenDaysAgo = new Date(now - 7 * 24 * 60 * 60 * 1000).toISOString();
74	    const todayStart = new Date(new Date().setHours(0, 0, 0, 0)).toISOString();
75	    const weekStart = new Date(now - 7 * 24 * 60 * 60 * 1000).toISOString();
76	    const thirtyDaysAgo = new Date(now - 30 * 24 * 60 * 60 * 1000).toISOString();
77	
78	    const [
79	      usersRes, jobsRes, resumesRes, creditsRes,
80	      dailyUsageRes, dailyJobsRes,
81	      paidPaymentsAllRes, paidPaymentsRangeRes,
82	      profilesRes,
83	      usage7dRes, usage30dRes,
84	      resumesTodayRes, resumesWeekRes, resumesMonthRes,
85	    ] = await Promise.all([
86	      supabase.auth.admin.listUsers({ perPage: 1000 }),
87	      supabase.from("jobs").select("id", { count: "exact", head: true }),
88	      supabase.from("resumes").select("id", { count: "exact", head: true }),
89	      supabase.from("usage_logs").select("credits_used"),
90	      supabase.from("usage_logs").select("credits_used, created_at, user_id").gte("created_at", rangeStartISO).lte("created_at", rangeEndISO),
91	      supabase.from("jobs").select("created_at").gte("created_at", rangeStartISO).lte("created_at", rangeEndISO),
92	      // Revenue: all paid payments
93	      supabase.from("payments").select("amount, currency").eq("status", "paid"),
94	      // Revenue: range paid payments with daily breakdown
95	      supabase.from("payments").select("amount, currency, created_at").eq("status", "paid").gte("created_at", rangeStartISO).lte("created_at", rangeEndISO),
96	      // Profiles for conversion rate
97	      supabase.from("profiles").select("plan"),
98	      // Active users 7d / 30d (always absolute, not range-dependent)
99	      supabase.from("usage_logs").select("user_id").gte("created_at", sevenDaysAgo),
100	      supabase.from("usage_logs").select("user_id").gte("created_at", thirtyDaysAgo),
101	      // Resumes processed today/week/month (always absolute)
102	      supabase.from("resumes").select("id", { count: "exact", head: true }).gte("created_at", todayStart),
103	      supabase.from("resumes").select("id", { count: "exact", head: true }).gte("created_at", weekStart),
104	      supabase.from("resumes").select("id", { count: "exact", head: true }).gte("created_at", thirtyDaysAgo),
105	    ]);
106	
107	    const allUsers = usersRes.data?.users ?? [];
108	    const totalUsers = allUsers.length;
109	    const totalJobs = jobsRes.count ?? 0;
110	    const totalResumes = resumesRes.count ?? 0;
111	    const totalCreditsUsed = creditsRes.data?.reduce((sum: number, l: any) => sum + (l.credits_used || 0), 0) ?? 0;
112	
113	    // Revenue
114	    const totalRevenue = paidPaymentsAllRes.data?.reduce((sum: number, p: any) => sum + (p.amount || 0), 0) ?? 0;
115	    const mrrRange = paidPaymentsRangeRes.data?.reduce((sum: number, p: any) => sum + (p.amount || 0), 0) ?? 0;
116	
117	    // Conversion rate
118	    const profiles = profilesRes.data ?? [];
119	    const paidUsers = profiles.filter((p: any) => p.plan && p.plan !== "free").length;
120	    const conversionRate = totalUsers > 0 ? Math.round((paidUsers / totalUsers) * 100) : 0;
121	
122	    // Active users
123	    const activeUsers7d = new Set(usage7dRes.data?.map((l: any) => l.user_id) ?? []).size;
124	    const activeUsers30d = new Set(usage30dRes.data?.map((l: any) => l.user_id) ?? []).size;
125	
126	    // Avg resumes per job
