131	    const resumesWeek = resumesWeekRes.count ?? 0;
132	    const resumesMonth = resumesMonthRes.count ?? 0;
133	
134	    // Daily chart aggregation — build day-by-day map for the range
135	    const totalRangeDays = Math.ceil((rangeEndDate.getTime() - rangeStartDate.getTime()) / (24 * 60 * 60 * 1000)) + 1;
136	    const dailyMap: Record<string, { credits: number; jobs: number; signups: number; revenue: number; active_users: number }> = {};
137	    for (let i = totalRangeDays - 1; i >= 0; i--) {
138	      const d = new Date(rangeEndDate.getTime() - i * 24 * 60 * 60 * 1000);
139	      const key = d.toISOString().slice(0, 10);
140	      dailyMap[key] = { credits: 0, jobs: 0, signups: 0, revenue: 0, active_users: 0 };
141	    }
142	
143	    const dailyActiveUsers: Record<string, Set<string>> = {};
144	    dailyUsageRes.data?.forEach((l: any) => {
