18	function isQualityText(text: string): boolean {
19	  if (!text || text.trim().length < 30) return false;
20	  const words = text.split(/\s+/).filter(w => /^[a-zA-Z]{2,}$/.test(w));
21	  const totalWords = text.split(/\s+/).length;
22	  const wordRatio = words.length / Math.max(totalWords, 1);
23	
24	  // Relaxed threshold for longer texts
25	  if (text.length > 500 && wordRatio > 0.2 && words.length > 15) return true;
26	
27	  // Resume keyword check: if text has common resume words, accept it
28	  if (text.length > 200) {
